'use strict';
/** White Orchard exploration uses the existing task identities and map coordinates. */
(()=>{
 const {tasks,hubs}=window.PHOENIX_ROUTE,pins=window.PHOENIX_MAP.markers;
 const refs={power:'https://primagames.com/eguides/the-witcher-3-wild-hunt-eguide/appendices-and-compendiums/places-of-power/white-orchard',powerRoute:'https://www.gamerguides.com/the-witcher-3-wild-hunt/guide/white-orchard/activities/place-of-power-locations',nests:'https://www.gamerguides.com/the-witcher-3-wild-hunt/guide/white-orchard/activities/monster-nests',sites:'https://www.gamerguides.com/the-witcher-3-wild-hunt/guide/white-orchard/activities/abandoned-sites-white-orchard',camps:'https://www.gamerguides.com/the-witcher-3-wild-hunt/guide/white-orchard/activities/bandit-camps-white-orchard',guarded:'https://www.gamerguides.com/the-witcher-3-wild-hunt/guide/white-orchard/activities/guarded-treasure-white-orchard',local:'https://www.gamebanshee.com/thewitcher3/walkthrough/location-whiteorchard.php',dirty:'https://www.gamebanshee.com/thewitcher3/walkthrough/dirtyfunds.php',mill:'https://www.gamebanshee.com/thewitcher3/walkthrough/temerianvaluables.php',skull:'https://witcher.fandom.com/wiki/Crystal_skull'};
 // A camp clear is not evidence that its associated multi-step quest is complete.
 for(const [pin,id,quest,name] of [['banditcamp-4','camp-dirty-funds','q-dirty','Dirty Funds · deserter camp'],['banditcamp-5','camp-viper-ruins','q-viper','Viper ruins · deserter camp']]){
  const prior=tasks[quest];tasks[id]={name,home:prior.home,view:'explore-'+id,type:'discovery',category:'exploration',intro:'A shared exploration stop on the regional route.',why:'Clear this location as part of the nearby quest outing.',requirements:'Inspect the defenders before entering.',reward:'Camp loot; quest and diagram records stay separate.',sections:[],sources:[...prior.sources],map:true};pins.find(p=>p.id===pin).task=id;pins.find(p=>p.id===pin).name=name;hubs.find(h=>h.id===prior.home).items.push(id);
 }
 const categories=[
  {id:'power',name:'Places of Power',art:'gwent-r15/woodland.webp',intro:'Six stones. Draw from each once for its ability point; repeat visits refresh its Sign bonus.',ids:['pop-cackler','pop-cemetery','pop-north','pop-sawmill','pop-bridge','pop-bear']},
  {id:'camps',name:'Bandit camps',art:'art-r13/q-deserter-card.webp',intro:'A regional loop from the eastern roads through the south and west, ending at the northern camp.',ids:['banditcamp-6','camp-viper-ruins','banditcamp-2','banditcamp-1','banditcamp-3','camp-dirty-funds']},
  {id:'nests',name:'Monster nests',art:'art-r13/q-beast-card.webp',intro:'Bring a suitable bomb before making the east-to-north nest circuit.',ids:['monsternest-3','monsternest-2','monsternest-1']},
  {id:'treasure',name:'Guarded treasure',art:'art-r13/q-temerian-card.webp',intro:'Shoreline caches, marshland and the cemetery crypt. The approach matters as much as the fight.',ids:['guarded-5','guarded-1','guarded-2','guarded-4','guarded-3']},
  {id:'hunts',name:'Hidden treasure hunts',art:'art-r13/q-dirty-card.webp',intro:'Follow documents to their destinations. These cards open the same treasure-hunt walkthroughs used by quest clusters.',ids:['q-temerian','q-deserter','q-dirty']},
  {id:'water',name:'Water caches',art:'art-r13/q-cargo-card.webp',intro:'Recover the southern cache and the garrison’s sunken spoils on separate outings.',ids:['smugglers-1','spoils-1']},
  {id:'sites',name:'Abandoned sites',art:'art-r13/q-firestarter-card.webp',intro:'Restore the roadside shrine and sawmill. The Abandoned Village itself is a different location.',ids:['abandoned-1','abandoned-2']},
  {id:'discoveries',name:'Other discoveries',art:'art-r13/q-missing-card.webp',intro:'Opening-camp keepsake, battlefield search and a village farming caution.',ids:['poi-4','poi-1','cow-pasture-warning']},
  {id:'travel',name:'Signposts',art:'white-orchard-map.webp',intro:'A suggested discovery circuit. A visited mark records discovery, not a combat accomplishment.',ids:['signpost-8','signpost-10','signpost-9','signpost-3','signpost-1','signpost-2','signpost-4','signpost-6','signpost-5','signpost-7']},
  {id:'preparation',name:'Equipment enhancements',art:'gwent-r15/gabor.webp',intro:'Reusable stops for temporary equipment bonuses. A mark means reviewed and used, not permanently completed.',ids:['grindstone-village','grindstone-3','grindstone-4','armourerstable-1']}
 ];
 const details={};
 function put(id,threat,approach,steps,fixed,variable,done,links=[],sources=[],uncertainty=''){
  const task=tasks[id],cat=categories.find(c=>c.ids.includes(id));
  details[id]={id,category:cat.id,threat,approach,steps,fixed,variable,done,links,sources:[...new Set([...sources,...task.sources])],uncertainty};task.exploration=true;task.completionDefinition=done;
  if(!task.stages){task.requirements=threat;task.intro=approach;task.reward=fixed;task.sections=[['Approach',approach],['Threat & preparation',threat],['Actions',steps.join(' ')],['Verified rewards',fixed],['Possible variable loot',variable],['Done means',done]];}
 }
 const power={
  'pop-cackler':['Quen','Reach Cackler Bridge from the village’s northeastern road; continue northeast to the stone beside the nest.','Ghouls and a nearby nest. Bring a nest-destroying bomb if clearing both stops.',['monsternest-2']],
  'pop-cemetery':['Igni','From the Mill, take the road north into the cemetery; the stone stands in front of the chapel.','Wraith. Use your silver sword; dodge its reappearance and use Yrden if you need it held in one area.',['guarded-3','diagram-viper-silver']],
  'pop-north':['Aard','Continue north from the cemetery into the woods toward the ghoul nest.','Ghouls beside the stone. Avoid drawing power while enemies can interrupt you.',['monsternest-1']],
  'pop-sawmill':['Axii','From Sawmill head northeast into the field between the two routes toward the garrison.','Wraith; wolves may roam the approach. Keep space to dodge and avoid pulling a second group.',['abandoned-2']],
  'pop-bridge':['Quen','Cross at Broken Bridge, follow the uphill trail southwest then south, and look just east of the trail.','No fixed guardian is documented for this stone. Watch the wooded approach.',['banditcamp-1']],
  'pop-bear':['Yrden','From Abandoned Village follow the eastern road toward the river; look south of the road in the trees.','Bear. Leave a clear retreat path; bait a swipe, dodge, and take a short opening rather than trading hits.',['abandoned-1']]
 };
 for(const [id,[sign,approach,threat,links]] of Object.entries(power))put(id,threat,approach,['Make the immediate area safe.','Hold the draw interaction until it finishes; simply touching the stone is not the ability-point reward.'],`One ability point on this stone’s first draw; a temporary ${sign} intensity bonus on a successful draw.`,'No additional item is guaranteed by drawing power.','Drew power fully from this specific stone at least once.',links,[refs.power,refs.powerRoute]);
 const nestApproach={
  'monsternest-3':'From Crossroads, head east and down to the nest. Return once you have a bomb; the opening ride does not require clearing it.',
  'monsternest-2':'Follow the road northeast from the village past Cackler Bridge. The nest and Quen stone sit close together.',
  'monsternest-1':'From Mill travel north past the cemetery, then continue into the woods to the nest beside the Aard stone.'
 };
 for(const [id,approach] of Object.entries(nestApproach))put(id,'Ghouls. Carry Samum, Grapeshot or Dancing Star; a stronger survivor may appear after the blast.',approach,['Defeat the surface ghouls.','Use the nest interaction to plant a suitable bomb, then move clear.','Handle any emerging guardian and loot the destroyed nest.'],'The nest is destroyed; no fixed named item is promised.','Nest remains and monster drops vary.','Destroyed this nest and collected its accessible nest loot.',id==='monsternest-1'?['pop-north']:id==='monsternest-2'?['pop-cackler']:[],[refs.nests]);
 const camps={
  'banditcamp-6':['From Crossroads head southwest toward the small bridge. Search the southern side after clearing it.',['Take the bridge defenders from one end so they cannot surround you.','Remove the ranged threat when you can reach it safely, then search the chest south of the bridge.'],[]],
  'camp-viper-ruins':['Approach the ruined fort west of Ransacked Village, east of White Orchard. Use the sloping fallen masonry to climb into the ruins.',['Clear the deserters before climbing further.','Search the upper ruin’s chest; use the shared diagram entry for the precise Viper acquisition.'],['diagram-viper-steel','q-viper']],
  'banditcamp-2':['From Ford follow the southern woodland approach to the camp; inspect the clearing before committing.',['Keep the camp edge behind you and separate the defenders.','When the site is safe, use Witcher Senses to find the camp containers.'],[]],
  'banditcamp-1':['From Broken Bridge head southwest into the forest. Watch the route as well as the camp.',['Work around the outside to stop the archer firing into the melee.','Clear the remaining defenders and search the chest beneath the tent.'],['pop-bridge']],
  'banditcamp-3':['From Sawmill travel northwest into the wooded camp. Make this stop after checking the restored settlement.',['Assess the defenders from outside their camp.','Fight with room to retreat and search the tents and marked containers afterward.'],['abandoned-2']],
  'camp-dirty-funds':['Follow the Dirty Funds trail east from the northern notes camp; the large deserter camp is northwest of Cackler Bridge.',['Engage small groups at the edge rather than rushing into the middle.','Deal with the shielded leader, then search the leader’s tent and its treasure chests.'],['q-dirty']]
 };
 for(const [id,[approach,steps,links]] of Object.entries(camps))put(id,'Human defenders: steel sword, ranged attackers first when practical. Check displayed enemy levels; equipment and upscaling affect readiness.',approach,steps,id==='camp-viper-ruins'?'Viper steel diagram is in the ruins; record its acquisition separately.':'Camp containers are available once reached; no fixed named equipment is promised.','Weapons, armor, money and materials may vary.','Cleared the camp’s defenders and searched its principal treasure containers.',links,[id==='camp-dirty-funds'?refs.dirty:id==='camp-viper-ruins'?tasks['q-viper'].sources[0]:refs.camps]);
 const guarded={
  'guarded-5':['Drowners on the shore. Descending straight off the village cliff can drop you into the group.','From Ransacked Village work around to the riverbank south of the houses rather than jumping from the cliff.',['Clear the shore in manageable groups.','Search both chests in the shallow pit.'],[]],
  'guarded-1':['Drowners around a wreck. Keep your footing and avoid fighting while boxed against the river.','Follow the riverbank southeast from Woesong Bridge toward the wreck.',['Make the shore safe before wading in.','Search the partially submerged crate and chest around the wreck.'],[]],
  'guarded-2':['Swamp gas and nearby drowners. Ignite gas only from a safe distance and wait for the blast before entering.','Take the western garrison road to the marsh’s southern edge, then follow the marsh west to the small island and body.',['Check the gas and nearby monsters before approaching.','If necessary, disperse the gas from outside it, then reach and loot the chest.'],[]],
  'guarded-4':['Wolves around a wagon on the garrison approach. Keep the pack in front of you.','Follow the eastern river road toward the garrison; inspect the wagon on the swamp approach.',['Defeat the wolves without letting the pack surround you.','Search the chest in the wagon and the chest beside it.'],[]],
  'guarded-3':['Wraith in the cemetery crypt. Use your silver sword and leave room to dodge.','From Mill go north to the chapel. The crypt is beneath the cemetery, separate from drawing power outside.',['Open the chapel approach with Aard if needed and enter the crypt.','Defeat the wraith and search the witcher remains and containers.','Open the silver-diagram entry to record that acquisition separately.'],['pop-cemetery','diagram-viper-silver','q-viper']]
 };
 for(const [id,[threat,approach,steps,links]] of Object.entries(guarded))put(id,threat,approach,steps,id==='guarded-3'?'Viper silver sword diagram and Kolgrim’s letter are found in the crypt.':'No fixed named equipment reward is verified for this cache.','Container equipment, materials and money may vary.','Dealt with the immediate danger and searched this site’s principal treasure containers.',links,[id==='guarded-3'?refs.local:refs.guarded],id==='guarded-2'||id==='guarded-4'?'Some guide tables transpose these two garrison encounters. The wagon/wolves and western gas-cache descriptions are used here; confirm against the live scene.':'');
 put('abandoned-1','Ghouls at the roadside shrine. Fight away from the shrine before attempting to inspect it.','Follow the road east from Abandoned Village toward the bridge, stopping at the roadside shrine.',['Clear the ghouls and allow the restoration scene to finish.','Check the returning herbalist; this is not the ruined village from Devil by the Well.'],'Residents return, including an herbalist.','Check current ingredient stock; optional containers and drops vary.','Cleared the site and saw the residents return.',['pop-bear','herbalist-2'],[refs.sites,refs.local]);
 put('abandoned-2','Ghouls at the sawmill; check nearby roaming beasts before starting.','Follow the western garrison road to Sawmill, then go west of its signpost.',['Clear the enemies and let the restoration scene finish.','Inspect the returned merchant and the building to the north.'],'Residents return, including the sawmill merchant.','Building loot and current merchant stock vary.','Cleared the site and saw the residents return.',['shopkeeper-2','banditcamp-3','grindstone-3'],[refs.sites,refs.local]);
 put('smugglers-1','Water and possible nearby hostiles. Keep an easy route back to shore and watch the breath meter when submerged.','From the road east of Abandoned Village approach the bridge over the river south of Ford. Search beneath and around the crossing.',['Make the bank safe and use Witcher Senses to inspect the cache area.','Collect the marked goods, surfacing whenever needed; sort loot on shore.'],'No fixed named item is verified.','Recovered equipment, materials and valuables vary.','Searched the marked cache containers and returned to safe ground.',['abandoned-1'],[refs.sites], 'The exact container contents and encounter roster are not verified; the mapped cache location comes from the credited marker dataset.');
 put('spoils-1','A submerged search. Avoid exhausting your breath while inspecting containers.','Reach the river east of Nilfgaardian Garrison and swim toward the mapped spoils.',['Use Witcher Senses at the marker to locate the submerged container.','Dive, collect the spoils, then return to the surface before sorting them.'],'No fixed named item is verified.','Sunken-container contents vary.','Recovered the marked underwater spoils.',['blacksmith-1'],['https://witcher.fandom.com/wiki/Spoils_of_War'],'Exact loot and underwater enemies have not been independently verified.');
 put('poi-4','Opening-area ghouls. Collect the keepsake early; it is reported to disappear after The Beast of White Orchard is completed.','Return to the opening campsite near Crossroads. Search the ground northwest of Roach’s initial position with Witcher Senses.',['Clear the opening enemies if they remain.','Locate the highlighted crystal skull and pick it up.'],'Crystal skull, an optional quest item.','No equipment upgrade is promised.','Picked up the crystal skull in game.',['q-lilac'],[refs.skull,'https://www.gamebanshee.com/thewitcher3/walkthrough/lilacandgooseberries.php']);details['poi-4'].risk='Collect the skull before completing The Beast of White Orchard. Its later story use stays behind spoiler controls in the relevant quest.';
 put('poi-1','Battlefield scavengers. Expect ghouls around the dead and check the scene before searching.','Reach the battlefield north of Ransacked Village; combine the search with Missing in Action.',['Use Witcher Senses to search bodies and containers along the battlefield.','Read recovered documents; follow Dune’s brother-search objectives in the quest walkthrough.'],'Searchable battlefield bodies and documents; no fixed equipment reward is verified.','Battlefield loot varies.','Reviewed and searched the battlefield route; this does not complete Missing in Action.',['q-missing'],[refs.local]);
 put('cow-pasture-warning','Repeated cow farming can trigger a powerful defensive monster. This is a caution, not a suggested fight.','The village cow pasture is near Woesong Bridge.',['Avoid using repeated cow slaughter as an early income route.','If the defensive monster appears and outmatches you, leave rather than treating it as a routine camp clear.'],'No reward is recommended for this caution.','Not a farming or loot recommendation.','Reviewed the cow-farming warning.',[],[],'The trigger details and monster level are not verified for your settings.');
 for(const id of categories.find(c=>c.id==='travel').ids){const t=tasks[id],location=t.sections.find(s=>s[0]==='Location')?.[1].split('. Open')[0]||t.name;put(id,'Reach the signpost safely; no fixed combat encounter is assigned to this travel stop.',location+'. Use the map to approach by road.',['Approach the signpost until the game discovers it.','Check that it is available on your game map; return to a signpost to fast travel.'],'A discovered fast-travel destination.','No loot reward is assigned.','Discovered this signpost in game.',[],[]);}
 for(const id of categories.find(c=>c.id==='preparation').ids){const t=tasks[id],table=id==='armourerstable-1';put(id,'A preparation stop, not a cleared encounter. Watch for nearby threats before interacting.',t.sections.find(s=>s[0]==='Location')[1].split('. Open')[0]+'.',['Interact with the '+(table?'armorer’s table':'grindstone')+'.','Check the temporary equipment bonus in game before departing.'],table?'Temporary armor enhancement.':'Temporary weapon enhancement.','No loot reward is assigned.','Visited and used this station at least once; the temporary bonus can expire.',[],[refs.local]);}
 // Treasure hunts retain their canonical quest records, choices and objective controls.
 for(const [id,threat,approach,steps,fixed,links] of [
  ['q-temerian','River approach: watch for drowners and manage breath.','At the bridge northwest of the village, search the corpse on the west bank for the Temerian Lily Key.',['Unlock the submerged chest and read the Blood-Soaked Military Orders.','Follow the hunt to the building at Mill, clear the cellar entrance with Aard, and search the stash.'],'Temerian Lily Key and military orders start the trail; the cellar source lists a Soaked Letter and five Temerian Rye.',['q-deserter']],
  ['q-deserter','Northern wilderness and any remaining threats along the route.','Search the isolated spy camp northwest of Cackler Bridge.',['Read the Spy’s Notes, then follow the hunt to Mill.','The sealed chest needs the Temerian Lily Key from the riverside corpse; check the shared stash once.'],'Spy’s Notes establish the lead; this shares the Mill treasure with Temerian Valuables.',['q-temerian']],
  ['q-dirty','Wolves at the notes camp; deserters and a shielded leader at the destination.','Search the abandoned notes camp northeast of Mill.',['Read the Scrawled Notes and follow the trail east.','Clear the deserter camp, then search the leader’s tent and its chests.'],'Scrawled Notes establish the hunt; no fixed named equipment reward is promised.',['camp-dirty-funds']]
 ])put(id,threat,approach,steps,fixed,'Most treasure contents vary; shared containers do not provide a second copy for each quest.','Completed this treasure hunt in game, including its required documents and final stash.',links,[id==='q-dirty'?refs.dirty:refs.mill]);
 // Regional cross-links share IDs; never copy completion records for nearby clusters.
 for(const [hub,ids] of [['hub-arrival',['monsternest-3','banditcamp-6','poi-4']],['hub-missing',['camp-viper-ruins','guarded-5','monsternest-2']],['hub-viper',['guarded-3','camp-viper-ruins']],['hub-temerian',['q-deserter','guarded-3']],['hub-deserter',['q-temerian','camp-dirty-funds']]])for(const id of ids){const h=hubs.find(h=>h.id===hub);if(!h.items.includes(id))h.items.push(id);}
 window.PHOENIX_EXPLORATION={categories,details,refs};
})();
